<!DOCTYPE html>
<html>
<head>
  <title>WastedToken Mint</title>
  <style>
    body {
      font-family: sans-serif;
      margin: 0;
      overflow: hidden;
      background-color: #1a1a1a;
    }

    #hero-container {
      width: 100vw;
      height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    #coin-hero {
      border: 1px solid #333;
      box-shadow: 0px 5px 15px rgba(0, 0, 0, 0.7);
    }

    .edition {
      display: flex;
      align-items: center;
      margin: 20px;
      width: 150px;
    }

    .edition-canvas {
      border: 1px solid #333;
      box-sizing: border-box;
    }

    .buy {
      background-color: #ffcc00;
      color: black;
      border: none;
      padding: 8px 12px;
      cursor: pointer;
      font-size: 14px;
      transition: background-color 0.3s ease;
    }

    .buy:disabled {
        opacity: 0.5;
        cursor: not-allowed;
    }

    #about-section {
      width: 80%;
      margin: 0 auto;
      text-align: center;
      background-color: #222;
      padding: 20px;
      border-radius: 10px;
    }

    #about-section h2 {
      color: #eee;
    }
  </style>
</head>
<body>

  <div id="hero-container">
    <canvas id="coin-hero"></canvas>
  </div>

  <div id="about-section">
    <h2>WastedToken Mint</h2>
    <p>We craft meticulously designed collectible challenge coins, blending digital artistry with tangible rarity. Each coin represents a milestone, a reward, or simply a prized possession.  Explore our limited editions and join the WastedToken community.</p>
  </div>

  <div class="edition" data-edition="bronze" data-state="available">
    <canvas class="edition-canvas"></canvas>
    <button class="buy">Add to cart</button>
  </div>
  <div class="edition" data-edition="silver" data-state="available">
    <canvas class="edition-canvas"></canvas>
    <button class="buy">Add to cart</button>
  </div>
  <div class="edition" data-edition="gold" data-state="sold-out">
    <canvas class="edition-canvas"></canvas>
    <button class="buy" disabled>SOLD OUT</button>
  </div>
  <div class="edition" data-edition="black" data-state="coming-soon">
    <canvas class="edition-canvas"></canvas>
    <button class="buy">Add to cart</button>
  </div>

  <script>
    const canvas = document.getElementById('coin-hero');
    const ctx = canvas.getContext('2d');
    canvas.width = 300;
    canvas.height = 300;

    let angle = 0;
    let xOffset = 0;
    let yOffset = 0;

    function renderFrame() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Coin rendering
      ctx.fillStyle = '#808080'; // Metallic Gray
      ctx.beginPath();
      ctx.ellipse(150, 150, 120, 120, angle, 0, 2 * Math.PI);
      ctx.fill();

      // Front Face - Emblem
      ctx.fillStyle = '#000';
      ctx.beginPath();
      ctx.arc(130, 100, 20, 0, 2 * Math.PI); // Circle for emblem
      ctx.fill();

       // Back Face - Token Count
      ctx.fillStyle = '#000';
      ctx.font = '16px Arial';
      ctx.textAlign = 'center';
      ctx.fillText('10,000 TOKENS', 130, 180);


      // Reeded Edge (Simplified) - just a subtle line for visual effect
      ctx.strokeStyle = '#555';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.strokeRect(0, 270, canvas.width, 30);


      // Specular Highlight (Simple) -  a glowing dot
      ctx.fillStyle = 'gold';
      ctx.fillRect(150 + 60 * Math.cos(angle), 150 + 60 * Math.sin(angle), 10, 10);


      angle += 0.02;
      xOffset += 0.01;
      yOffset += 0.01;

      requestAnimationFrame(renderFrame);
    }

    function setTime(t) {
        angle = t * 2 * Math.PI;
        xOffset = t * 0.5;
        yOffset = t * 0.5;
        requestAnimationFrame(renderFrame);
    }

    function pause() {
      cancelAnimationFrame(renderFrame);
    }

    setTime(0); // Start animation
  </script>
</body>
</html>
